      'Marta Silva is on vacation on Fri, Nov 6'
    );
  });

  it('rejects a shift that ends before it starts', () => {
    expect(check('2026-11-04 14:00:00', '2026-11-04 06:00:00')).toBe(
      'A shift must end after it starts'
    );
  });
});

